INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flooded-quarry', 'west', 'the-haul-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-boundary', 'north', 'the-sunken-drove', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-haul-road', 'door', 'The Haul Road', 'The track the stone went out on, wide enough for a sledge and graded to keep a loaded one from running away downhill. Nothing has hauled anything along it in a very long time, and the ruts have filled with a fine pale grit that takes a footprint perfectly.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-haul-road', 'east', 'the-flooded-quarry', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-haul-road', 'west', 'the-spoil-banks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-spoil-banks', 'door', 'The Spoil Banks', 'Long heaps of quarry waste to either side, gone over to grass and thorn, so the track runs between two low green walls that were not put there by anyone who thought of them as walls. Rabbits have been at the banks. Something bigger has been at the rabbits.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spoil-banks', 'east', 'the-haul-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spoil-banks', 'west', 'the-plank-bridge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-plank-bridge', 'door', 'The Plank Bridge', 'The beck again, narrower and faster up here, and across it three heavy planks laid on stone footings and pinned. It is not a bridge anyone was proud of. It has outlasted the one that was, downstream, which is the whole reason this road exists.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plank-bridge', 'east', 'the-spoil-banks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plank-bridge', 'west', 'the-thorn-lane', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plank-bridge', 'south', 'the-drovers-stance', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-drovers-stance', 'door', 'The Drover''s Stance', 'A flat acre of cropped turf inside a wall of piled stone, with a spring-fed trough at one end and the black rings of old fires at the other. Beasts were held here overnight, and men sat up with them. The grass still grows differently where they stood.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drovers-stance', 'north', 'the-plank-bridge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-thorn-lane', 'door', 'The Thorn Lane', 'Blackthorn grown in from both sides until the way through is a green tunnel barely wider than a cow, arched over and dark even at noon. It catches at you the whole length. There is wool on the thorns, grey with age.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thorn-lane', 'east', 'the-plank-bridge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thorn-lane', 'west', 'the-broken-cross', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-broken-cross', 'door', 'The Broken Cross', 'A wayside cross on a stepped base, snapped off at the shaft, the head lying in the grass where it fell and half sunk into it. People stopped here to be somewhere for a moment. The base is cut all over with the marks they left doing it.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-cross', 'east', 'the-thorn-lane', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-cross', 'west', 'the-high-verge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-high-verge', 'door', 'The High Verge', 'Open ground along the top of the ridge, the drove running broad and grassy with the whole valley laid out south of it. You can see the paved road down there, a pale line through the trees, and anything that is on it. Anything on it can see you.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-verge', 'east', 'the-broken-cross', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-verge', 'west', 'the-gorse-tunnel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-verge', 'north', 'the-sheep-fold', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-sheep-fold', 'door', 'The Sheep-Fold', 'A round fold of drystone, roofless, the wall still shoulder-high all the way round and the doorway a gap you turn sideways through. Out of the wind, out of sight, and out of the weather. Somebody swept it, not so very long ago.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sheep-fold', 'south', 'the-high-verge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-gorse-tunnel', 'door', 'The Gorse Tunnel', 'Gorse taller than a man closed over the drove, so the way is a low green pipe going west, floored in its own dead needles. It is loud to walk through and there is no seeing out of it. It smells, absurdly, of coconut.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gorse-tunnel', 'east', 'the-high-verge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gorse-tunnel', 'south', 'the-sunken-drove', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-sunken-drove', 'door', 'The Sunken Drove', 'The last of the drove drops off the ridge in a channel worn waist-deep by four hundred years of hooves, so narrow at the bottom that you walk it with a hand on each bank. It comes out on the paving at the boundary stone, which is where it always meant to.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunken-drove', 'north', 'the-gorse-tunnel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunken-drove', 'south', 'the-old-boundary', NULL);
